// The fixtures in testdata are a profile of a module example.com/m and a
// diff in the format of git diff --unified=0 (generated by git, then trimmed
// by hand). Outside the exclusions (main.go, internal/helper/), the profile
// holds 18 statements, 12 covered: 66.67%, all in the package internal/a.
// The diff touches 12 statements of it, 9 covered: 75.0%. testdata/coverage.json
// sets diff_min to 75 and total_target to 65, so that every rule holds, and
// leaves package_min null.
const trimFixture = "example.com/m/"

// matchFixture selects the files the summary lists one by one, as the
// default -match does.
var matchFixture = regexp.MustCompile(`_(resource|data_source)\.go$`)

// gateFixture copies testdata/coverage.json to a temporary directory with
// edits and returns the options for run, with testdata/change.diff as the
// diff.
func gateFixture(t *testing.T, edit func(string) string) options {
	t.Helper()
	dir := t.TempDir()
	cfg, err := os.ReadFile(filepath.Join("testdata", "coverage.json"))
	if err != nil {
		t.Fatal(err)
	}
	text := string(cfg)
	if edit != nil {
		text = edit(text)
	}
	write(t, filepath.Join(dir, "coverage.json"), text)
	return options{
		match:      matchFixture,
		trim:       trimFixture,
		configPath: filepath.Join(dir, "coverage.json"),
		diffPath:   filepath.Join("testdata", "change.diff"),
	}
}

// write writes content to path, failing the test on an error.
func write(t *testing.T, path, content string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
}

// set returns an edit of the configuration that gives a numeric field
// another value.
func set(field, value string) func(string) string {
	re := regexp.MustCompile(`"` + field + `": [0-9.]+`)
	return func(s string) string { return re.ReplaceAllString(s, `"`+field+`": `+value) }
}

// packageMin returns an edit of the configuration that sets package_min,
// null in the fixture.
func packageMin(value string) func(string) string {
	return func(s string) string { return strings.Replace(s, `"package_min": null`, `"package_min": `+value, 1) }
}

// addField returns an edit of the configuration that adds a field, given as
// `"name": value`, before the others.
func addField(field string) func(string) string {
	return func(s string) string { return strings.Replace(s, "{", "{\n  "+field+",", 1) }
}

// runGate runs the gate on testdata/profile.txt and returns its output.
func runGate(t *testing.T, opts options) (string, error) {
	t.Helper()
	var out strings.Builder
	err := run(&out, strings.NewReader(""), filepath.Join("testdata", "profile.txt"), opts)
	return out.String(), err
}

// TestGateRules checks each rule passing and failing, through the report.
func TestGateRules(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name    string
		edit    func(string) string
		noDiff  bool
		fails   bool
		want    []string
		notWant []string
	}{
		{
			name: "everything passes, diff exactly at the threshold",
			want: []string{
				"All rules pass.",
				"| Diff: covered share of the statements the change touches | 75.0% (9 of 12) | at least 75% | pass |",
				"| Total: coverage outside the exclusions | 66.67% (12 of 18) | at least 65% | pass |",
				"| `internal/a/a.go` | 4 | 2 | 7-9 |",
				"| `internal/a/a_resource.go` | 4 | 4 |  |",
				"| `internal/a/é.go` | 4 | 3 | 3 |",
				"(2 changed Go files)",
				"Excluded from every rule: `main.go`, `internal/helper/`.",
				"| Packages: coverage of each package | lowest 66.7% (`internal/a`); 0 of 1 under 65% | none yet: `package_min` is not set | monitored |",
				"Monitored, not enforced: `package_min` in `.coverage.json` is not set yet. Once it is set to 65, every package must stay at 65% or more.",
				"| Package | Statements | Covered | Coverage | Points to 65% |",
				"| `internal/a` | 18 | 12 | 66.7% | reached |",
				"**66.7%** of 18 statements across 3 files, outside the exclusions of `.coverage.json`",
				"| `internal/a/a_resource.go` | 6 | 4 | 66.7% |",
			},
			notWant: []string{"sp ace.go", "h.go", "a_test.go", "removed.go", "README", "add tests"},
		},
		{
			name:  "diff under the threshold",
			edit:  set("diff_min", "75.1"),
			fails: true,
			want:  []string{"**The gate fails**", "| 75.0% (9 of 12) | at least 75.1% | **FAIL** |"},
		},
		{
			name: "total just over the target",
			edit: set("total_target", "66.66"),
			want: []string{"All rules pass.", "| Total: coverage outside the exclusions | 66.67% (12 of 18) | at least 66.66% | pass |"},
		},
		{
			name:  "total under the target, packages monitored against it",
			edit:  set("total_target", "70"),
			fails: true,
			want: []string{
				"**The gate fails**",
				"| Total: coverage outside the exclusions | 66.67% (12 of 18) | at least 70% | **FAIL** |",
				"The total is under the 70% of `total_target`: add tests, starting with the least covered packages and files, which the tables below list first.",
				"| Packages: coverage of each package | lowest 66.7% (`internal/a`); 1 of 1 under 70% | none yet: `package_min` is not set | monitored |",
				"| `internal/a` | 18 | 12 | 66.7% | 3.3 |",
			},
		},
		{
			name: "package_min set and met",
			edit: packageMin("60"),
			want: []string{
				"All rules pass.",
				"| Packages: coverage of each package | lowest 66.7% (`internal/a`); 0 of 1 under 60% | at least 60% per package | pass |",
				"Enforced: every package must be at 60% or more (`package_min`).",
				"| `internal/a` | 18 | 12 | 66.7% | reached |",
			},
			notWant: []string{"Monitored"},
		},
		{
			name:  "package_min set and missed",
			edit:  packageMin("70"),
			fails: true,
			want: []string{
				"| Total: coverage outside the exclusions | 66.67% (12 of 18) | at least 65% | pass |",
				"| Packages: coverage of each package | lowest 66.7% (`internal/a`); 1 of 1 under 70% | at least 70% per package | **FAIL** |",
				"Under the 70% of `package_min`: 1 of 1 packages.",
				"| `internal/a` | 18 | 12 | 66.7% | 3.3 |",
			},
		},
		{
			name:    "no diff given",
			noDiff:  true,
			want:    []string{"All rules pass.", "not measured (no diff given) | at least 75% | skipped |"},
			notWant: []string{"### Statements the change touches"},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			opts := gateFixture(t, tc.edit)
			if tc.noDiff {
				opts.diffPath = ""
			}
			out, err := runGate(t, opts)
			if tc.fails != errors.Is(err, errGateFailed) || (err != nil && !errors.Is(err, errGateFailed)) {
				t.Fatalf("run error = %v, want failure %v\n%s", err, tc.fails, out)
			}
			for _, w := range tc.want {
				if !strings.Contains(out, w) {
					t.Errorf("summary misses %q:\n%s", w, out)
				}
			}
			for _, w := range tc.notWant {
				if strings.Contains(out, w) {
					t.Errorf("summary has %q:\n%s", w, out)
				}
			}
		})
	}
}

// TestTotalRule checks the total rule on exact counts: a total exactly at
// the target holds, and an excluded file does not count.
func TestTotalRule(t *testing.T) {
	t.Parallel()
	files := map[string]*fileCoverage{
		"m/a.go":    {Name: "m/a.go", Total: 5, Covered: 4},
		"m/main.go": {Name: "m/main.go", Total: 5},
	}
	for _, tc := range []struct {
		target  float64
		exclude []string
		want    bool
	}{
		{target: 80, exclude: []string{"main.go"}, want: true},
		{target: 80.01, exclude: []string{"main.go"}, want: false},
		{target: 80, want: false}, // main.go counts: 4 of 10
		{target: 40, want: true},
	} {
		r := evaluate(gateInput{config: config{DiffMin: 75, TotalTarget: tc.target, Exclude: tc.exclude}}, files, "m/")
		if got := r.totalOK(); got != tc.want {
			t.Errorf("target %g, exclude %v: total %.2f%%, totalOK() = %v, want %v", tc.target, tc.exclude, r.totalPercent(), got, tc.want)
		}
	}
}

// TestGateDiffFromStdin checks that -diff - reads the diff from stdin.
func TestGateDiffFromStdin(t *testing.T) {
	t.Parallel()
	opts := gateFixture(t, nil)
	opts.diffPath = "-"
	diff, err := os.ReadFile(filepath.Join("testdata", "change.diff"))
	if err != nil {
		t.Fatal(err)
	}
	var out strings.Builder
	if err := run(&out, strings.NewReader(string(diff)), filepath.Join("testdata", "profile.txt"), opts); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "75.0% (9 of 12)") {
		t.Errorf("stdin diff not used:\n%s", out.String())
	}
}

// TestGateInputErrors checks that an invalid configuration, diff or profile
// is an input error, not a failed rule, and says what is wrong.
func TestGateInputErrors(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name string
		edit func(string) string
		opts func(*options)
		want string
	}{
		{"unknown field", func(s string) string { return strings.Replace(s, `"diff_min"`, `"diff_minimum"`, 1) }, nil, `coverage.json: json: unknown field "diff_minimum"`},
		// The fields of the former ratchet are refused, not ignored.
		{"ratchet_tolerance", addField(`"ratchet_tolerance": 0.5`), nil, `coverage.json: json: unknown field "ratchet_tolerance"`},
		{"baseline_file", addField(`"baseline_file": ".coverage-baseline"`), nil, `coverage.json: json: unknown field "baseline_file"`},
		{"diff_min out of range", set("diff_min", "0"), nil, "diff_min must be in (0, 100], got 0"},
		{"diff_min over 100", set("diff_min", "100.5"), nil, "diff_min must be in (0, 100], got 100.5"},
		{"total_target out of range", set("total_target", "101"), nil, "total_target must be in (0, 100], got 101"},
		{"total_target missing", func(s string) string {
			return regexp.MustCompile(`"total_target": [0-9.]+,`).ReplaceAllString(s, "")
		}, nil, "total_target must be in (0, 100], got 0"},
		{"several problems, sorted", func(s string) string { return set("total_target", "0")(set("diff_min", "101")(s)) }, nil,
			"diff_min must be in (0, 100], got 101; total_target must be in (0, 100], got 0"},
		{"package_min out of range", packageMin("0"), nil, "package_min must be null or in (0, 100], got 0"},
		{"package_min not a number", packageMin(`"75"`), nil, "cannot unmarshal string"},
		{"absolute exclusion", func(s string) string { return strings.Replace(s, `"main.go"`, `"/main.go"`, 1) }, nil, `exclude entry "/main.go"`},
		{"escaping exclusion", func(s string) string { return strings.Replace(s, `"main.go"`, `"../main.go"`, 1) }, nil, `exclude entry "../main.go"`},
		{"missing diff", nil, func(o *options) { o.diffPath = "testdata/absent.diff" }, "no such file"},
		{"malformed diff", nil, func(o *options) {
			o.diffPath = filepath.Join(filepath.Dir(o.configPath), "bad.diff")
			if err := os.WriteFile(o.diffPath, []byte("+++ b/x\n@@ -1 @@\n"), 0o600); err != nil {
				panic(err)
			}
		}, "malformed hunk header"},
		{"missing config", nil, func(o *options) { o.configPath = "testdata/absent.json" }, "no such file"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			opts := gateFixture(t, tc.edit)
			if tc.opts != nil {
				tc.opts(&opts)
			}
			_, err := runGate(t, opts)
			if err == nil || errors.Is(err, errGateFailed) || !strings.Contains(err.Error(), tc.want) {
				t.Errorf("run error = %v, want an input error containing %q", err, tc.want)
			}
		})
	}
	var out strings.Builder
	if err := run(&out, nil, "testdata/absent.out", options{match: matchFixture}); err == nil {
		t.Error("a missing profile is not an error")
	}
	bad := filepath.Join(t.TempDir(), "bad.out")
	write(t, bad, "not a profile\n")
	if err := run(&out, nil, bad, options{match: matchFixture}); err == nil {
		t.Error("a malformed profile is not an error")
	}
}

// TestSummaryWithoutConfig checks that without -config, run prints the
// summary over every file and no gate.
func TestSummaryWithoutConfig(t *testing.T) {
	t.Parallel()
	var out strings.Builder
	if err := run(&out, nil, filepath.Join("testdata", "profile.txt"), options{match: matchFixture, trim: trimFixture}); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "**46.2%** of 26 statements across 5 files (") || strings.Contains(out.String(), "Coverage gate") {
		t.Errorf("summary without config:\n%s", out.String())
	}
}

// TestParseDiff checks the changed ranges read from testdata/change.diff,
// and that a malformed diff is refused.
func TestParseDiff(t *testing.T) {
	t.Parallel()
	f, err := os.Open(filepath.Join("testdata", "change.diff"))
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = f.Close() }()
	changes, err := parseDiff(f)
	if err != nil {
		t.Fatal(err)
	}
	want := map[string][]lineRange{
		"internal/a/a.go":          {{4, 4}, {9, 10}},
		"internal/a/a_resource.go": {{6, 6}},
		"internal/a/a_test.go":     {{2, 4}},
		"internal/helper/h.go":     {{1, 1}},
		"README.md":                {{1, 1}},
		"internal/a/sp ace.go":     {{1, 2}},
		"internal/a/é.go":          {{1, 3}},
	}
	if len(changes) != len(want) {
		t.Errorf("parsed %v, want %v", changes, want)
	}
	for name, ranges := range want {
		if got := changes[name]; len(got) != len(ranges) || (len(got) > 0 && got[0] != ranges[0]) || got[len(got)-1] != ranges[len(ranges)-1] {
			t.Errorf("%s: %v, want %v", name, got, ranges)
		}
	}

	for name, diff := range map[string]string{
		"hunk ends early":       "diff --git a/x b/x\n+++ b/x\n@@ -1 +1,2 @@\n+a\ndiff --git a/y b/y\n",
		"diff ends in a hunk":   "+++ b/x\n@@ -1,2 +1 @@\n-a\n",
		"malformed header":      "+++ b/x\n@@ -1 @@\n",
		"bad old range":         "+++ b/x\n@@ -a +1 @@\n",
		"bad new count":         "+++ b/x\n@@ -1 +1,z @@\n",
		"bad new start":         "+++ b/x\n@@ -1 +z @@\n",
		"path without b/":       "+++ x\n",
		"bad quoted path":       "+++ \"b/x\n",
		"header without @@ end": "+++ b/x\n@@ -1 +1 x\n",
	} {
		if _, err := parseDiff(strings.NewReader(diff)); err == nil {
			t.Errorf("%s: parsed without error", name)
		}
	}
}

// TestPackagesOf checks the grouping of files by package, least covered
// first, without the exclusions and the packages without statements.
func TestPackagesOf(t *testing.T) {
	t.Parallel()
	f, err := os.Open(filepath.Join("testdata", "packages.txt"))
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = f.Close() }()
	files, err := parseProfile(f)
	if err != nil {
		t.Fatal(err)
	}
	cfg := config{Exclude: []string{"main.go", "internal/helper/"}}
	got := packagesOf(files, trimFixture, cfg.excluded)
	want := []packageCoverage{
		{dir: "internal/c/d", total: 3, covered: 0},
		{dir: "internal/b", total: 4, covered: 1},
		{dir: "internal/e", total: 4, covered: 1},
		{dir: "internal/a", total: 6, covered: 2},
		{dir: "internal/f", total: 2, covered: 2},
	}
	if !slices.Equal(got, want) {
		t.Errorf("packages %+v, want %+v", got, want)
	}
}

// update makes TestGateReportGolden rewrite its golden files instead of
// comparing with them: go test -run TestGateReportGolden -update.
var update = flag.Bool("update", false, "rewrite the golden reports in testdata")

// TestGateReportGolden compares whole reports with testdata/gate-*.golden,
// so that a change to the report shows in review. go test -run
// TestGateReportGolden -update rewrites them.
func TestGateReportGolden(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name string
		edit func(string) string
		diff string // "" for testdata/change.diff, "none" for no diff
	}{
		{name: "pass"},
		{name: "fail", edit: func(s string) string {
			return packageMin("70")(set("total_target", "70")(set("diff_min", "80")(s)))
		}},
		{name: "total", edit: set("total_target", "70"), diff: "none"},
		{name: "nostatement", diff: "diff --git a/README.md b/README.md\n--- a/README.md\n+++ b/README.md\n@@ -1 +1 @@\n-a\n+b\n"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			opts := gateFixture(t, tc.edit)
			switch tc.diff {
			case "":
			case "none":
				opts.diffPath = ""
			default:
				opts.diffPath = filepath.Join(t.TempDir(), "change.diff")
				write(t, opts.diffPath, tc.diff)
			}
			out, err := runGate(t, opts)
			if err != nil && !errors.Is(err, errGateFailed) {
				t.Fatal(err)
			}
			golden := filepath.Join("testdata", "gate-"+tc.name+".golden")
			if *update {
				write(t, golden, out)
			}
			want, err := os.ReadFile(golden)
			if err != nil {
				t.Fatal(err)
			}
			if out != string(want) {
				t.Errorf("report differs from %s:\n%s", golden, out)
			}
		})
	}
}

// TestParseDiffContextLines checks a diff with context lines (-U1 here): a
// context line counts on both sides of the hunk.
func TestParseDiffContextLines(t *testing.T) {
	t.Parallel()
	diff := "diff --git a/x.go b/x.go\n--- a/x.go\n+++ b/x.go\n" +
		"@@ -1,3 +1,3 @@\n a\n-b\n+c\n d\n" +
		"@@ -9,2 +9,3 @@\n e\n+f\n g\n"
	changes, err := parseDiff(strings.NewReader(diff))
	if err != nil {
		t.Fatal(err)
	}
	if got, want := changes["x.go"], []lineRange{{1, 3}, {9, 11}}; !slices.Equal(got, want) {
		t.Errorf("x.go: %v, want %v", got, want)
	}
}

// TestParseDiffErrorMessages checks that a parse error says the line and
// the problem, and that a read error comes through.
func TestParseDiffErrorMessages(t *testing.T) {
	t.Parallel()
	for diff, want := range map[string]string{
		"diff --git a/x b/x\n+++ b/x\n@@ -1 +1,2 @@\n+a\ndiff --git a/y b/y\n": `line 5: hunk ends early at "diff --git a/y b/y"`,
		"+++ b/x\n@@ -1 @@\n":          `line 2: malformed hunk header "@@ -1 @@"`,
		"+++ x\n":                      `line 1: new path "x" does not start with b/`,
		"+++ b/x\n@@ -1,2 +1 @@\n-a\n": "the diff ends inside a hunk",
	} {
		if _, err := parseDiff(strings.NewReader(diff)); err == nil || err.Error() != want {
			t.Errorf("parseDiff(%q) error = %v, want %q", diff, err, want)
		}
	}
	readErr := errors.New("read failed")
	if _, err := parseDiff(iotest.ErrReader(readErr)); !errors.Is(err, readErr) {
		t.Errorf("parseDiff on a failing reader: error = %v, want %v", err, readErr)
	}
}

// TestEvaluateDiffBlocks checks which blocks and files the diff rule counts.
func TestEvaluateDiffBlocks(t *testing.T) {
	t.Parallel()
	files := map[string]*fileCoverage{
		"m/x.go": {Name: "m/x.go", Total: 6, Covered: 2, counts: []blockCount{
			{startLine: 20, endLine: 22, stmts: 2},
			{startLine: 1, endLine: 3, stmts: 2, covered: true},
			{startLine: 10, endLine: 12, stmts: 2},
		}},
		"m/y.go": {Name: "m/y.go", Total: 1, Covered: 1, counts: []blockCount{{startLine: 1, endLine: 1, stmts: 1, covered: true}}},
	}
	in := gateInput{
		config: config{DiffMin: 75, TotalTarget: 80},
		changes: map[string][]lineRange{
			"x.go":      {{1, 25}},
			"y.go":      {{5, 6}}, // touches no block
			"z.go":      {{1, 1}}, // not in the profile
			"x_test.go": {{1, 1}},
			"notes.md":  {{1, 1}},
		},
	}
	r := evaluate(in, files, "m/")
	want := []changedFile{{name: "x.go", changed: 6, covered: 2, uncovered: []lineRange{{10, 12}, {20, 22}}}}
	if !reflect.DeepEqual(r.diffFiles, want) || r.diffChanged != 6 || r.diffCovered != 2 || r.diffIgnored != 1 || !r.diffChecked {
		t.Errorf("diff rule: files %+v, %d of %d covered, %d ignored, checked %v", r.diffFiles, r.diffCovered, r.diffChanged, r.diffIgnored, r.diffChecked)
	}
	if r.total != 7 || r.totalCovered != 3 {
		t.Errorf("total %d of %d, want 3 of 7", r.totalCovered, r.total)
	}
}
